-- Produits BOOOM ajoutés par le patron (04/11/2026) : vraie photo (img/booom/…), prix de l'affiche BOOOM.
-- photo = petite vignette (48 px) ; son empreinte renvoie au vrai fichier img/booom/… (règle des catalogues légers).
-- hand_added : l'import automatique BOOOM (toutes les 6 h) ne les masque pas et ne remplace pas leur photo.
alter table public.shop_products add column if not exists hand_added boolean not null default false;
insert into public.shop_photo_files (h, path) values ('ee6864f3548231fed65875d09321f49e', 'img/booom/pates-antica.webp'), ('71799720a3932e10b10e96ee57822461', 'img/booom/huile-tournesol.webp'), ('047af0bebd523cf8d6c422fd9b85e970', 'img/booom/piles-xsus.webp'), ('d1729f821a4c82736a6b30ecc19a8cce', 'img/booom/lingettes-baby-booom.webp') on conflict (h) do update set path = excluded.path;
do $mig$
declare d text := pg_get_functiondef('public.booom_import(bigint)'::regprocedure); n text;
begin
  n := replace(d, 'update shop_products set available = false where shop_id = sid and available and not (id = any(seen));',
                  'update shop_products set available = false where shop_id = sid and available and not hand_added and not (id = any(seen));');
  n := replace(n, 'photo = coalesce(excluded.photo, shop_products.photo)',
                  'photo = case when shop_products.hand_added then shop_products.photo else coalesce(excluded.photo, shop_products.photo) end');
  if n = d or position('not hand_added' in n) = 0 or position('when shop_products.hand_added' in n) = 0 then raise exception 'booom_import: patch non appliqué'; end if;
  execute n;
end $mig$;
insert into public.shop_products (id, shop_id, category_id, name, description, price, photo, available, position, hand_added) values
  (md5('HOPBOOOM:85')::uuid, (select id from shops where code = 'HOPBOOOM'), md5('HOPBOOOM:cat:forts')::uuid, 'Antica · Spaghetti ou pâtes 400 g, au choix · ספגטי/פסטה אנטיקה', '400 g · formes au choix · 400 גרם · מבחר צורות', 2.9, 'data:image/webp;base64,UklGRrwAAABXRUJQVlA4ILAAAADwBQCdASowADAAPtFepk2oJSOiKqlZABoJYwDQMaAlkkEVTeNYOyJarDgjx+k65sc3H05ROmBOQAD+9ibhzjB/68z2clflBcsVK4pSSHf/b12T6WG3lubit8Ejni9vk+d3gINsBu38BPLgCRdi0JrfFTW8nmb7M7A0dISbKH037OZiUqeJii8ESJ79Okd6gJ+tE5CwX5TtzKKYX7DKHgJRKZwKH93F6hCzjULioAAAAA==', true, -4, true),
  (md5('HOPBOOOM:hop:huile-tournesol')::uuid, (select id from shops where code = 'HOPBOOOM'), md5('HOPBOOOM:cat:forts')::uuid, 'Huile de tournesol ou canola 900 ml · שמן חמניות/קנולה', '900 ml · 900 מ״ל', 6.9, 'data:image/webp;base64,', true, -3, true),
  (md5('HOPBOOOM:hop:piles-xsus')::uuid, (select id from shops where code = 'HOPBOOOM'), md5('HOPBOOOM:cat:forts')::uuid, 'X-SUS · 10 piles alcalines AA / AAA · מארז 10 סוללות אלקליין', '10 piles alcalines AA et AAA · 10 סוללות אלקליין AA ו-AAA', 10, 'data:image/webp;base64,', true, -2, true),
  (md5('HOPBOOOM:hop:lingettes')::uuid, (select id from shops where code = 'HOPBOOOM'), md5('HOPBOOOM:cat:forts')::uuid, 'Baby BOOOM · Lingettes bébé 5 × 72 · מארז מגבונים לתינוקות', '5 paquets de 72 lingettes · 5 חבילות · 72 יח׳ בחבילה', 15, 'data:image/webp;base64,', true, -1, true)
on conflict (id) do update set name = excluded.name, description = excluded.description, price = excluded.price, photo = excluded.photo, position = excluded.position, hand_added = true;

